from pybricks.parameters import Color

from function import FULL_SPEED, StopAtColorhsv, TOLERANCE, black, calibration_with_wall, detect_color, robot_straight, robot_turn, run_front_claw_stalled

# Initialize variables.
satellite_distance = 0
offset = 170

def come_collect_():
    robot_straight(400, -80)
    robot_turn(500, -91)
    StopAtColorhsv(-200, black, TOLERANCE)
    robot_straight(400, -50)
    robot_turn(300, 90)
    robot_straight(300, -1000)
    robot_turn(300, -91)
    robot_straight(200, 130)

def satellite_col():
    global satellite_distance, offset
    if detect_color() == Color.WHITE:
        satellite_distance = 241
    if detect_color() == Color.GREEN:
        satellite_distance = 441
    if detect_color() == Color.BLUE:
        satellite_distance = 641
    if detect_color() == Color.YELLOW:
        satellite_distance = 841
    if detect_color() == Color.RED:
        satellite_distance = 1041
    if detect_color() == Color.NONE:
        robot_straight(200, 170)
        detect_color()
        satellite_col()
        offset = offset + 120
    run_front_claw_stalled(-300)

def mission4Block():
    satellite_col()
    robot_turn(FULL_SPEED, -90)
    robot_straight(FULL_SPEED, 200)
    robot_turn(FULL_SPEED, 90)
    robot_straight(250, 1000)
    robot_turn(FULL_SPEED, -90)
    robot_straight(500, 545)
    robot_turn(FULL_SPEED, -90)
    StopAtColorhsv(200, black, TOLERANCE)
    robot_straight(400, satellite_distance)
    robot_turn(500, 90)
    run_front_claw_stalled(300)
    robot_straight(500, 70)
    come_collect_()
    satellite_col()
    go_put_()
    come_collect_()
    robot_turn(300, 2)
    satellite_col()
    go_put_()
    come_collect_()
    robot_turn(300, 2)
    satellite_col()
    go_put_()

def go_put_():
    robot_turn(FULL_SPEED, 90)
    robot_straight(FULL_SPEED, 200)
    robot_turn(FULL_SPEED, 90)
    robot_straight(300, 170 + offset)
    robot_turn(FULL_SPEED, -90)
    robot_straight(500, 545)
    robot_turn(FULL_SPEED, -90)
    StopAtColorhsv(200, black, TOLERANCE)
    robot_straight(400, satellite_distance)
    robot_turn(FULL_SPEED, 90)
    run_front_claw_stalled(300)
    robot_straight(500, 70)


